from __future__ import annotations

import argparse
import json
import re
from dataclasses import dataclass
from pathlib import Path

TEXT_EXTENSIONS = {".php", ".inc", ".phtml", ".html", ".htm", ".js", ".ts", ".py", ".sql"}
EXCLUDED_DIRS = {
    ".git", ".hermclaw", "model_runtime", "agent_core", "docs",
    "android_app", "node_modules", "vendor", ".venv", "venv",
    "__pycache__", "dist", "build"
}

@dataclass(frozen=True)
class Pattern:
    label: str
    regex: str
    weight: int

PATTERNS = [
    Pattern("benutzer_array_def", r"\bfunction\s+benutzer_array\s*\(", 60),
    Pattern("benutzer_array", r"\bbenutzer_array\s*\(", 22),
    Pattern("benutzer_liste", r"\bbenutzer_liste\b", 18),
    Pattern("GET_suche", r"\$_GET\s*\[\s*['\"]suche['\"]\s*\]", 22),
    Pattern("POST_suche", r"\$_POST\s*\[\s*['\"]suche['\"]\s*\]", 16),
    Pattern("input_suche", r"\bname\s*=\s*['\"]suche['\"]", 18),
    Pattern("suche", r"\bsuche\b", 3),
    Pattern("filter", r"\bfilter\w*\b", 2),
    Pattern("status", r"\bstatus\w*\b", 1),
    Pattern("empty_state", r"(Noch keine Benutzer|Keine Benutzer|keine Treffer|tabelle__leer)", 8),
    Pattern("rechte", r"(rechte_pruefen|berechtigung|berechtigungen)", 1),
]

GENERIC_ONLY = {"suche", "filter", "status", "rechte", "empty_state"}
USER_SYMBOLS = {"benutzer_array_def", "benutzer_array", "benutzer_liste"}
SEARCH_SYMBOLS = {"GET_suche", "POST_suche", "input_suche"}

def excluded(path: Path, root: Path) -> bool:
    rel = path.relative_to(root)
    return any(part in EXCLUDED_DIRS for part in rel.parts[:-1])

def _eligibility(rel: str, counts: dict[str, int]) -> tuple[bool, str]:
    lower = rel.lower()
    user_named = "benutzer" in lower or "/user" in lower or lower.startswith("user")
    has_user_symbol = any(name in counts for name in USER_SYMBOLS)
    has_search_symbol = any(name in counts for name in SEARCH_SYMBOLS)

    if user_named and (has_user_symbol or counts):
        return True, "Benutzer-bezogener Pfad mit Codebelegen."
    if has_user_symbol and has_search_symbol:
        return True, "Benutzersymbol und konkreter Suchparameter im selben Codepfad."
    return False, "Nur generische oder fachfremde Treffer."

def discover(root: Path) -> dict:
    candidates = []
    scanned = 0

    for path in root.rglob("*"):
        if not path.is_file() or excluded(path, root) or path.suffix.lower() not in TEXT_EXTENSIONS:
            continue
        try:
            if path.stat().st_size > 2_000_000:
                continue
        except OSError:
            continue

        scanned += 1
        rel = path.relative_to(root).as_posix()
        text = path.read_text(encoding="utf-8", errors="replace")
        lower_rel = rel.lower()

        score = 0
        if "benutzer" in lower_rel:
            score += 35
        elif "/user" in lower_rel or lower_rel.startswith("user"):
            score += 12

        if rel.startswith("nav/"):
            score += 5
        elif rel.startswith("inc/"):
            score += 8
        elif rel.startswith("api/"):
            score += 1

        counts = {}
        snippets = []
        lines = text.splitlines()

        for pattern in PATTERNS:
            matches = list(re.finditer(pattern.regex, text, flags=re.IGNORECASE | re.MULTILINE))
            if not matches:
                continue

            counts[pattern.label] = len(matches)
            score += pattern.weight * min(len(matches), 6)

            for match in matches[:2]:
                line_no = text.count("\n", 0, match.start()) + 1
                start = max(0, line_no - 2)
                end = min(len(lines), line_no + 1)
                snippet = "\n".join(
                    f"{i + 1}: {lines[i][:240]}" for i in range(start, end)
                )
                snippets.append({
                    "label": pattern.label,
                    "line": line_no,
                    "snippet": snippet,
                })

        if score <= 0:
            continue

        eligible, reason = _eligibility(rel, counts)
        candidates.append({
            "path": rel,
            "score": score,
            "handoff_eligible": eligible,
            "eligibility_reason": reason,
            "pattern_counts": counts,
            "snippets": snippets[:10],
        })

    candidates.sort(
        key=lambda item: (
            not item["handoff_eligible"],
            -item["score"],
            item["path"],
        )
    )

    eligible_count = sum(1 for item in candidates if item["handoff_eligible"])
    return {
        "schema": 2,
        "profile": "benutzerfilter",
        "scanned_files": scanned,
        "eligible_count": eligible_count,
        "candidate_count": min(12, len(candidates)),
        "candidates": candidates[:12],
    }

def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--root", required=True)
    parser.add_argument("--output", required=True)
    args = parser.parse_args()

    root = Path(args.root).resolve()
    result = discover(root)

    output = Path(args.output)
    output.write_text(
        json.dumps(result, ensure_ascii=False, indent=2) + "\n",
        encoding="utf-8",
    )

    print(f"[DISCOVERY] {result['scanned_files']} Dateien geprüft.")
    print(f"[DISCOVERY] {result['eligible_count']} Kandidat(en) für Handoff zugelassen.")

    for idx, item in enumerate(result["candidates"], start=1):
        labels = ", ".join(item["pattern_counts"].keys()) or "nur Dateiname"
        marker = "ELIGIBLE" if item["handoff_eligible"] else "IGNORED"
        print(
            f"[DISCOVERY] {idx}. [{marker}] {item['path']} | "
            f"score={item['score']} | {labels}"
        )

    print(f"[DISCOVERY] Ergebnis: {output}")
    return 0

if __name__ == "__main__":
    raise SystemExit(main())

import unittest

from model_runtime.fast_handoff import fallback, validate

class FastHandoffTests(unittest.TestCase):
    def setUp(self):
        self.discovery = {
            "candidates": [
                {
                    "path": "nav/settings_benutzer.php",
                    "score": 120,
                    "handoff_eligible": True,
                    "pattern_counts": {
                        "benutzer_liste": 2,
                        "empty_state": 1,
                    },
                    "snippets": [
                        {
                            "snippet": (
                                "10: $benutzer_liste = "
                                "benutzer_array();"
                            )
                        }
                    ],
                },
                {
                    "path": "inc/funktionen_benutzer.php",
                    "score": 110,
                    "handoff_eligible": True,
                    "pattern_counts": {
                        "benutzer_array_def": 1,
                        "benutzer_array": 1,
                    },
                    "snippets": [
                        {
                            "snippet": (
                                "20: function benutzer_array("
                                "int $limit = 100): array"
                            )
                        }
                    ],
                },
                {
                    "path": "wiki.php",
                    "score": 80,
                    "handoff_eligible": False,
                    "pattern_counts": {
                        "GET_suche": 1,
                        "suche": 3,
                    },
                    "snippets": [],
                },
            ]
        }

    def test_fallback_uses_only_eligible_candidates(self):
        handoff = fallback(self.discovery)
        validate(handoff, self.discovery)

        self.assertIn(
            "nav/settings_benutzer.php",
            handoff["target_paths"],
        )
        self.assertIn(
            "inc/funktionen_benutzer.php",
            handoff["target_paths"],
        )
        self.assertNotIn(
            "wiki.php",
            handoff["target_paths"],
        )

    def test_validate_rejects_ineligible_existing_candidate(self):
        handoff = fallback(self.discovery)
        handoff["target_paths"].append("wiki.php")

        with self.assertRaises(ValueError):
            validate(handoff, self.discovery)

if __name__ == "__main__":
    unittest.main()
